"use client";
import {
  useId,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { useContinuity } from "./use-continuity";
import { CardPreview } from "./card-preview";
import "./source-stack.css";
import { useControllableState } from "./use-controllable-state";
export interface SourceItem {
  id: string;
  title: string;
  kind: string;
  content: ReactNode;
  color?: string;
}
/** Sources keep one composition through pile, spread and top-layer inspection. */
export interface SourceStackProps {
  items: SourceItem[];
  color?: string;
  duration?: number;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
  style?: CSSProperties;
  openLabel?: ReactNode;
  closeLabel?: ReactNode;
}
export function SourceStack({
  items,
  color,
  duration,
  open,
  defaultOpen = false,
  onOpenChange,
  className = "",
  style,
  openLabel = "Unfold",
  closeLabel = "Gather",
}: SourceStackProps) {
  const [spread, setSpread] = useControllableState(
    open,
    defaultOpen,
    onOpenChange,
  );
  const { root, change } = useContinuity(),
    id = useId(),
    toggle = useRef<HTMLButtonElement>(null);
  return (
    <div
      ref={root}
      style={
        {
          "--roc-duration": duration ? `${duration}ms` : undefined,
          ...style,
        } as CSSProperties
      }
      className={`roc-sources ${spread ? "is-spread" : ""} ${className}`}
      onKeyDown={(e) => {
        if (e.key === "Escape" && spread) {
          e.stopPropagation();
          change(() => setSpread(false));
          toggle.current?.focus();
        }
      }}
    >
      <button
        type="button"
        ref={toggle}
        className="roc-text-button roc-source-toggle"
        aria-expanded={spread}
        aria-controls={id}
        onClick={() => change(() => setSpread(!spread))}
      >
        {spread ? closeLabel : openLabel} <span>↗</span>
      </button>
      <div
        id={id}
        className="roc-source-items"
        inert={!spread}
        aria-hidden={!spread}
      >
        {items.map((item, index) => (
          <article
            key={item.id}
            data-roc-item
            className="roc-source"
            style={{
              left: spread
                ? `${items.length <= 1 ? 50 : 16 + (index / (items.length - 1)) * 68}%`
                : "50%",
              top: spread ? 35 : 30 + index * 6,
              transform: `translateX(-50%) rotate(${spread ? 0 : (index - (items.length - 1) / 2) * 7}deg)`,
              zIndex: index + 1,
            }}
          >
            <CardPreview
              label={item.title}
              previewHeight={175}
              compositionWidth={360}
              openLabel="Inspect ↗"
              closeLabel="Return ↙"
              color={
                color
                  ? `color-mix(in srgb, ${color} ${12 + index * 12}%, white)`
                  : item.color
              }
            >
              <span className="roc-eyebrow">{item.kind}</span>
              <h3>{item.title}</h3>
              <div className="roc-source-content">{item.content}</div>
            </CardPreview>
          </article>
        ))}
      </div>
    </div>
  );
}

"use client";
import { useCallback, useLayoutEffect, useRef } from "react";

/** Measure before changing layout; retain actual nodes and retarget from their visible pose.
 * Layout retargeting preserves the current measured pose; release velocity is not preserved.
 */
export function useContinuity(duration = 480) {
  const root = useRef<HTMLDivElement>(null);
  const before = useRef(new Map<HTMLElement, DOMRect>());
  const animations = useRef(new Map<HTMLElement, Animation>());
  const change = useCallback((update: () => void) => {
    before.current.clear();
    root.current
      ?.querySelectorAll<HTMLElement>("[data-roc-item]")
      .forEach((node) => {
        before.current.set(node, node.getBoundingClientRect());
      });
    update();
  }, []);
  useLayoutEffect(() => {
    if (!before.current.size) return;
    const configured = Number.parseFloat(
      root.current
        ? getComputedStyle(root.current).getPropertyValue("--roc-duration")
        : "",
    );
    const timing = Number.isFinite(configured) ? configured : duration;
    const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
    for (const [node, old] of before.current) {
      animations.current.get(node)?.cancel();
      if (!node.isConnected || reduced) continue;
      const next = node.getBoundingClientRect();
      if (!next.width || !next.height) continue;
      const scale = node.dataset.rocScale !== "false";
      const animation = node.animate(
        [
          {
            translate: `${old.x - next.x}px ${old.y - next.y}px`,
            scale: scale
              ? `${old.width / next.width} ${old.height / next.height}`
              : "1",
          },
          { translate: "0px 0px", scale: "1" },
        ],
        { duration: timing, easing: "cubic-bezier(.22,.8,.25,1)" },
      );
      animations.current.set(node, animation);
      void animation.finished
        .then(() => {
          if (animations.current.get(node) === animation)
            animations.current.delete(node);
        })
        .catch(() => {});
    }
    before.current.clear();
  });
  useLayoutEffect(
    () => () => {
      animations.current.forEach((a) => a.cancel());
    },
    [],
  );
  return { root, change };
}

"use client";
import {
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { presentationSample } from "./presentation-spring";
import "./card-preview.css";
import { useControllableState } from "./use-controllable-state";

type Pose = {
  x: number;
  y: number;
  scale: number;
  height: number;
  radius: number;
  reveal: number;
  scroll: number;
};
const keys: (keyof Pose)[] = [
  "x",
  "y",
  "scale",
  "height",
  "radius",
  "reveal",
  "scroll",
];
export interface CardPreviewProps {
  children: ReactNode;
  label: string;
  style?: CSSProperties;
  open?: boolean;
  className?: string;
  color?: string;
  previewHeight?: number;
  compositionWidth?: number;
  defaultOpen?: boolean;
  openLabel?: string;
  closeLabel?: string;
  onOpenChange?: (open: boolean) => void;
}
/** One composition in one native dialog, embedded while closed and in the top
 * layer while reading. No portal handoff, clone, or content reflow on opening.
 * The return slot is always present and remeasured while closing. */
export function CardPreview({
  children,
  label,
  className = "",
  color,
  previewHeight = 240,
  compositionWidth = 480,
  defaultOpen = false,
  openLabel = "Open preview ↗",
  closeLabel = "Return ↙",
  onOpenChange,
  open: controlled,
  style,
}: CardPreviewProps) {
  const anchor = useRef<HTMLDivElement>(null),
    dialog = useRef<HTMLDialogElement>(null);
  const surface = useRef<HTMLElement>(null),
    viewport = useRef<HTMLDivElement>(null),
    content = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null),
    closeButton = useRef<HTMLButtonElement>(null);
  const control = useRef<{ open: () => void; close: () => void } | null>(null);
  const [desired, setDesired] = useControllableState(
    controlled,
    defaultOpen,
    onOpenChange,
  );
  const request = useRef(setDesired);
  request.current = setDesired;
  const [reading, setReading] = useState(false);
  useLayoutEffect(() => {
    const slot = anchor.current!,
      modal = dialog.current!,
      paper = surface.current!,
      clip = viewport.current!,
      body = content.current!;
    let current: Pose,
      flight: {
        from: Pose;
        to: Pose;
        start: number;
        opening: boolean;
        done?: () => void;
      } | null = null;
    let raf = 0,
      active = false,
      closing = false,
      disposed = false;
    const reduced = matchMedia("(prefers-reduced-motion: reduce)");
    const slotPose = (): Pose => {
      const r = slot.getBoundingClientRect();
      return {
        x: r.x,
        y: r.y,
        scale: r.width / compositionWidth,
        height: previewHeight,
        radius: 8,
        reveal: 0,
        scroll: 0,
      };
    };
    const target = (): Pose => {
      const v = window.visualViewport,
        width = v?.width || innerWidth,
        height = v?.height || innerHeight;
      const w = Math.min(640, width - 40),
        scale = w / compositionWidth;
      const h = Math.min(body.scrollHeight * scale, height - 112);
      return {
        x: (v?.offsetLeft || 0) + (width - w) / 2,
        y: (v?.offsetTop || 0) + 64,
        scale,
        height: h,
        radius: 16,
        reveal: 1,
        scroll: 0,
      };
    };
    function paint() {
      paper.style.transform = active
        ? `translate3d(${current.x}px,${current.y}px,0)`
        : "none";
      paper.style.width = `${compositionWidth * current.scale}px`;
      paper.style.height = `${current.height}px`;
      paper.style.borderRadius = `${current.radius}px`;
      body.style.transform = `scale(${current.scale})`;
      clip.style.height = `${current.height}px`;
      clip.style.overflowY = active && !closing ? "auto" : "hidden";
      // A scaled composition retains its natural typesetting; only its physical
      // footprint changes. Keep scroll extent in those same projected coordinates.
      body.parentElement!.style.height = `${body.scrollHeight * current.scale}px`;
      if (closing) clip.scrollTop = current.scroll;
      modal.style.setProperty("--roc-reveal", String(current.reveal));
    }
    function sample(now: number) {
      if (!flight) return;
      for (const key of keys)
        current[key] = presentationSample(
          flight.from[key],
          flight.to[key],
          (now - flight.start) / 1000,
          flight.opening,
        ).position;
    }
    function tick(now: number) {
      if (!flight || disposed) return;
      // An anchor can move during resize/scroll while this paper is returning.
      if (closing) {
        const next = slotPose();
        if (
          ["x", "y", "scale"].some(
            (k) =>
              Math.abs(next[k as keyof Pose] - flight!.to[k as keyof Pose]) >
              0.01,
          )
        ) {
          sample(now);
          flight.from = { ...current };
          flight.to = next;
          flight.start = now;
        }
      }
      sample(now);
      const settled = keys.every((k) => {
        const s = presentationSample(
          flight!.from[k],
          flight!.to[k],
          (now - flight!.start) / 1000,
          flight!.opening,
        );
        const tolerance = k === "scale" || k === "reveal" ? 0.0001 : 0.04;
        return (
          Math.abs(s.position - flight!.to[k]) < tolerance &&
          Math.abs(s.velocity) < tolerance * 4
        );
      });
      if (reduced.matches || settled) {
        const done = flight.done;
        current = { ...flight.to };
        flight = null;
        paint();
        done?.();
      } else {
        paint();
        raf = requestAnimationFrame(tick);
      }
    }
    function run(to: Pose, opening: boolean, done?: () => void) {
      cancelAnimationFrame(raf);
      flight = {
        from: { ...current },
        to,
        start: performance.now(),
        opening,
        done,
      };
      tick(performance.now());
    }
    function finish() {
      active = false;
      closing = false;
      modal.close();
      modal.classList.remove("is-reading");
      modal.setAttribute("open", "");
      current = slotPose();
      clip.scrollTop = 0;
      paint();
      setReading(false);
      trigger.current?.focus({ preventScroll: true });
    }
    function close() {
      if (!active || closing) return;
      current.scroll = clip.scrollTop;
      closing = true;
      body.inert = true;
      run(slotPose(), false, finish);
    }
    function open() {
      if (active && !closing) return;
      if (!active) {
        current = slotPose();
        modal.close();
        modal.classList.add("is-reading");
        active = true;
        paint();
        modal.showModal();
      }
      closing = false;
      body.inert = false;
      setReading(true);
      run(target(), true);
      closeButton.current?.focus({ preventScroll: true });
    }
    control.current = { open, close };
    const fit = () => {
      if (!active) {
        current = slotPose();
        paint();
      } else if (!closing) run(target(), true);
    };
    const observer = new ResizeObserver(fit);
    observer.observe(slot);
    observer.observe(body);
    const cancel = (e: Event) => {
      e.preventDefault();
      e.stopPropagation();
      request.current(false);
    };
    modal.addEventListener("cancel", cancel);
    window.addEventListener("resize", fit);
    window.visualViewport?.addEventListener("resize", fit);
    current = slotPose();
    modal.setAttribute("open", "");
    body.inert = true;
    paint();
    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      observer.disconnect();
      modal.removeEventListener("cancel", cancel);
      window.removeEventListener("resize", fit);
      window.visualViewport?.removeEventListener("resize", fit);
      modal.close();
      control.current = null;
    };
  }, [compositionWidth, previewHeight]);
  useLayoutEffect(() => {
    if (desired) control.current?.open();
    else control.current?.close();
  }, [desired, compositionWidth, previewHeight]);
  return (
    <div
      className={`roc-card-preview ${className}`}
      style={{ "--roc-card-color": color, ...style } as CSSProperties}
    >
      <div
        ref={anchor}
        className="roc-return-slot"
        style={{ height: previewHeight }}
      >
        <dialog
          ref={dialog}
          className="roc-card-dialog"
          aria-label={label}
          onKeyDown={(e) => e.stopPropagation()}
          onPointerDown={(e) => {
            if (e.target === e.currentTarget && reading) setDesired(false);
          }}
        >
          <article ref={surface} className="roc-preview-paper" data-roc-item>
            <div ref={viewport} className="roc-preview-scroll">
              <div className="roc-preview-extent">
                <div
                  ref={content}
                  className="roc-preview-composition"
                  style={{ width: compositionWidth }}
                >
                  {children}
                </div>
              </div>
            </div>
          </article>
          <button
            ref={closeButton}
            hidden={!reading}
            type="button"
            className="roc-preview-close"
            onClick={() => setDesired(false)}
          >
            {closeLabel}
          </button>
        </dialog>
      </div>
      <button
        ref={trigger}
        type="button"
        className="roc-text-button roc-preview-trigger"
        aria-expanded={reading}
        onClick={() => setDesired(!desired)}
      >
        {openLabel}
      </button>
    </div>
  );
}

/** Analytic presentation spring, ported from Syuze src/spatial/spring.js and
 * presentation-motion.js. Presentation retargets position with zero initial
 * velocity, matching that viewer (not the canvas drag spring). */
export function presentationSample(
  from: number,
  to: number,
  seconds: number,
  opening: boolean,
) {
  const mass = opening ? 0.48 : 0.32,
    a = Math.sqrt(100 / mass);
  const d = from - to,
    t = Math.max(0, seconds),
    e = Math.exp(-a * t);
  return { position: to + d * (1 + a * t) * e, velocity: -d * a * a * t * e };
}

@import "./surface.css";
.roc-card-preview {
  width: 100%;
  position: relative;
  color: var(--roc-ink, #2c302c);
}
.roc-return-slot {
  position: relative;
  width: 100%;
}
.roc-card-dialog {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  padding: 0;
  margin: 0;
  border: 0;
  overflow: visible;
  background: transparent;
  color: inherit;
  box-sizing: border-box;
}
.roc-card-dialog:not([open]) {
  display: none;
}
.roc-card-dialog.is-reading {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100dvh;
  overflow: hidden;
}
.roc-card-dialog::backdrop {
  background: rgb(244 241 234 / calc(var(--roc-reveal, 0) * 0.78));
  backdrop-filter: blur(calc(var(--roc-reveal, 0) * 10px));
}
.roc-preview-paper {
  position: absolute;
  left: 0;
  top: 0;
  margin: 0;
  background: var(--roc-card-color, #fcfbf8);
  border: 1px solid #e1dfd4;
  box-shadow:
    0 2px 5px #252d2108,
    0 12px 32px #252d210a;
  overflow: clip;
  transform-origin: 0 0;
}
.roc-preview-scroll {
  width: 100%;
  overflow: hidden;
  overscroll-behavior: contain;
  scrollbar-width: thin;
}
.roc-preview-extent {
  position: relative;
  width: 100%;
}
.roc-preview-composition {
  position: absolute;
  left: 0;
  top: 0;
  transform-origin: 0 0;
  padding: 38px;
  font-size: 16px;
  line-height: 1.75;
  font-family: inherit;
  box-sizing: border-box;
}
.roc-preview-composition h3 {
  font:
    normal 32px/1.2 Georgia,
    serif;
  margin: 20px 0;
  letter-spacing: -0.025em;
}
.roc-preview-composition .roc-eyebrow {
  font-size: 11px;
}
.roc-preview-close {
  position: fixed;
  right: max(24px, env(safe-area-inset-right));
  top: max(16px, env(safe-area-inset-top));
  border: 1px solid #dddcd4;
  background: var(--roc-paper, #fcfbf8);
  border-radius: 24px;
  padding: 10px 16px;
  font: 13px system-ui !important;
  z-index: 1;
  opacity: var(--roc-reveal, 0);
}
.roc-preview-trigger {
  position: relative;
  min-height: 36px;
  margin-top: 8px;
}

/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: 2px solid var(--roc-accent, #64735f);
  outline-offset: 3px;
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}

"use client";
import { useState } from "react";
/** An optional owner, not a mandatory store or application provider. */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (next: T) => void] {
  const [local, setLocal] = useState(defaultValue),
    current = value === undefined ? local : value;
  return [
    current,
    (next) => {
      if (Object.is(current, next)) return;
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ];
}

@import "./surface.css";
.roc-sources {
  position: relative;
  height: 320px;
  width: 100%;
  max-width: 580px;
  margin: auto;
  container-type: inline-size;
}
.roc-source-toggle {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  z-index: 12;
}
.roc-source-items {
  position: absolute;
  inset: 45px 0 0;
}
.roc-source {
  position: absolute;
  width: min(146px, 30cqw);
  padding: 0;
  transform-origin: 0 0;
  transition: transform var(--roc-duration, 480ms)
    cubic-bezier(0.22, 0.8, 0.25, 1);
}
.roc-source h3 {
  font:
    normal 30px/1.15 Georgia,
    serif;
  letter-spacing: -0.02em;
  margin: 17px 0 12px;
}
.roc-source-content {
  font-size: 16px;
  line-height: 1.75;
}
.roc-source .roc-preview-trigger {
  font-size: 11px;
}
@media (prefers-reduced-motion: reduce) {
  .roc-source {
    transition: none;
  }
}
